const $=s=>document.querySelector(s);let state,project,session,busy=false;const el=(tag,text)=>{const e=document.createElement(tag);e.textContent=text;return e;};
async function api(path,body){const r=await fetch(path,{method:body?'POST':'GET',headers:{'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined});const d=await r.json();if(!r.ok)throw Error(d.error||'Error del servidor');return d;}
function error(e){$('#status').textContent=e.message;}
async function refresh(){state=await api('/api/state');project=state.projects[0];if(!project)throw Error('Proyecto no disponible. Vuelve a vincular desde el Mac.');$('#project').textContent=project.name;$('#permissions').textContent='Escritura: '+project.config.write+' · Ejecución: '+project.config.execute;const old=session;$('#session').replaceChildren(...state.sessions.map(s=>{const o=el('option',s.title);o.value=s.id;return o;}));session=state.sessions.some(s=>s.id===old)?old:state.sessions[0]?.id;$('#session').value=session||'';if(!$('#provider').options.length){$('#provider').replaceChildren(...state.providers.map(p=>{const o=el('option',p.name);o.value=p.id;return o;}));$('#provider').value=state.selected_provider;}await models();await messages();await actions();}
async function models(){try{const d=await api('/api/models?provider='+encodeURIComponent($('#provider').value));const old=$('#model').value;$('#model').replaceChildren(...d.models.map(m=>{const o=el('option',m.name||m.id);o.value=m.id;return o;}));if(d.models.some(m=>m.id===old))$('#model').value=old;}catch(e){$('#model').replaceChildren(el('option','Motor no disponible'));error(e);}}
async function messages(){if(!session)return;const rows=await api('/api/messages?session='+session+'&limit=40');$('#messages').replaceChildren(...rows.map(m=>{const a=el('article','');a.append(el('b',m.role==='user'?'Tú':'Agentic'),el('span',m.content));return a;}));}
async function actions(){if(!session)return;const d=await api('/api/proposals?session='+session);$('#actions').replaceChildren();let pending=false;for(const [kind,items] of [['extension',d.extensions||[]],['file',d.files||[]],['command',d.commands||[]]])for(const x of items.filter(a=>a.status==='pending')){pending=true;const card=el('div','');card.className='action';card.append(el('b',kind==='extension'?x.name:kind==='file'?x.path:'Terminal del proyecto'),el('pre',kind==='extension'?x.arguments:kind==='file'?x.content:x.command));for(const [text,approve] of [['Aprobar',true],['Rechazar',false]]){const b=el('button',text);b.onclick=async()=>{try{if(approve&&!confirm('¿Aprobar la acción completa mostrada en esta tarjeta?'))return;const path=kind==='file'?'/api/proposal/resolve':kind==='command'?'/api/command/resolve':'/api/extension/resolve';await api(path,{id:x.id,approve});await actions();}catch(e){error(e);}};card.append(b);}$('#actions').append(card);}if(!pending)$('#actions').textContent='Ninguna acción pendiente.';$('#resume').disabled=pending||d.run?.status!=='waiting';}
function activity(text){$('#activity').textContent=($('#activity').textContent+'\n'+text).slice(-16000);}
async function send(resume=false){if(busy||!session)return;busy=true;$('#send').disabled=true;$('#status').textContent='Generando en el Mac…';try{const body=resume?{session_id:session,resume:true}:{session_id:session,message:$('#prompt').value,provider:$('#provider').value,model:$('#model').value,agent:$('#agent').checked,retrieval:false,context:16384,max_tokens:1024,max_steps:12,temperature:.3};const r=await fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});if(!r.ok)throw Error((await r.json()).error);if(!resume)$('#prompt').value='';const answer=el('article','');answer.append(el('b','Agentic'));const text=el('span','');answer.append(text);$('#messages').append(answer);const reader=r.body.getReader(),decoder=new TextDecoder();let buffer='';let chars=0;function event(e){if(e.type==='delta'){text.textContent+=e.text;chars+=e.text.length;$('#status').textContent='Generando · '+chars+' caracteres';}if(e.type==='activity'){$('#status').textContent=e.text;activity(e.text);}if(e.type==='reasoning')activity(e.text);if(e.type==='tool_start')activity(e.name+' '+JSON.stringify(e.arguments));if(e.type==='tool')activity(e.name+' '+JSON.stringify(e.result).slice(0,4000));if(e.type==='metrics')$('#status').textContent='Salida: '+(e.usage?.completion_tokens??'…')+' tokens';if(e.type==='waiting')$('#status').textContent='Esperando tu revisión.';if(e.type==='done')$('#status').textContent='Completado en '+e.meta.seconds+' s';if(e.type==='error')throw Error(e.error);}while(true){const chunk=await reader.read();if(chunk.done)break;buffer+=decoder.decode(chunk.value,{stream:true});let i;while((i=buffer.indexOf('\n'))>=0){const line=buffer.slice(0,i);buffer=buffer.slice(i+1);if(line.trim())event(JSON.parse(line));}}if(buffer.trim())event(JSON.parse(buffer));await messages();await actions();}catch(e){error(e);}finally{busy=false;$('#send').disabled=false;}}
$('#compose').onsubmit=e=>{e.preventDefault();send();};$('#provider').onchange=models;$('#session').onchange=async()=>{session=$('#session').value;await messages();await actions();};$('#new').onclick=async()=>{try{session=(await api('/api/sessions',{project_id:project.id})).id;await refresh();}catch(e){error(e);}};$('#refresh').onclick=()=>refresh().catch(error);$('#resume').onclick=()=>send(true);refresh().catch(error);
